1138:     const item = ITEMS[arg];
1139:     if (!item) return;
1140:     if (p.money < item.price) { ui.toast('<b>NO CASH</b> · The counter is patient. Your wallet is not.', 'warn'); return; }
1141:     p.money -= item.price;
1142:     for (const [k,v] of Object.entries(item.effects || {})) p[k] = clamp((p[k] || 0) + v, 0, 100);
1143:     if (arg === 'beer' || arg === 'cider' || arg === 'whiskey') { state.stats.drinks++; p.intoxication = clamp(p.intoxication + (arg === 'whiskey' ? 16 : 8), 0, 100); }
1144:     state.time.minutes += 18; audio.cash();
1145:     ui.toast(`<b>ORDERED</b> · ${item.name}.`, '');
1146:     openBusiness(b.id); saveGame(true); return;
1147:   }
1148:   if (act === 'buy') {
1149:     const item = ITEMS[arg];
1150:     if (!item) return;
1151:     if (p.money < item.price) { ui.toast('<b>NO CASH</b> · The city does not extend credit to strangers.', 'warn'); return; }
1152:     p.money -= item.price; addItem(arg, 1); audio.cash();
