1375: function startTimingGame(opts) {
1376:   if (timingGame) return;
1377:   gameMode = 'timing';
1378:   player.moveInput(0, 0);
1379:   timingGame = {
1380:     rounds: Math.max(1, opts.rounds || 3), hits: 0, round: 0,
1381:     pos: 0, dir: 1, speed: .82 + Math.random() * .18, target: .5,
1382:     onComplete: opts.onComplete, done: false, details: []
1383:   };
1384:   const html = `<div class="timing-wrap">
1385:     <p class="timing-prompt">${esc(opts.prompt || 'HIT THE MARK')}</p>
1386:     <div class="timing-track" id="timing-track">
1387:       <div class="timing-zone" id="timing-zone"></div>
1388:       <div class="timing-marker" id="timing-marker"></div>
1389:       <div class="timing-ticks"></div>
1390:     </div>
1391:     <div class="timing-meta"><span id="timing-round">ROUND 1 / ${timingGame.rounds}</span><span id="timing-status">READY</span></div>
1392:     <button class="panel-action" id="timing-hit">HIT · SPACE</button>
1393:     <p class="panel-note">Click the track or press SPACE when the marker enters the bright zone. Perfect timing pays more.</p>
1394:   </div>`;
1395:   ui.openPanel({
1396:     kicker: opts.kicker || 'JOB', title: opts.title || 'SHIFT',
1397:     html,
1398:     onMount: (body) => {
1399:       const track = body.querySelector('#timing-track');
1400:       track?.addEventListener('pointerdown', (e) => { e.preventDefault(); timingHit(); });
1401:       body.querySelector('#timing-hit')?.addEventListener('click', timingHit);
1402:     }
1403:   });
1404:   setTimingTarget();
1405:   requestAnimationFrame(() => {
1406:     const m = $('timing-marker');
1407:     if (m) m.style.left = '0%';
1408:   });
1409: }
