1423: function updateTiming(dt) {
1424:   if (!timingGame || timingGame.done) return;
1425:   const g = timingGame;
1426:   g.pos += g.dir * g.speed * dt;
1427:   if (g.pos >= 1) { g.pos = 1; g.dir = -1; }
1428:   if (g.pos <= 0) { g.pos = 0; g.dir = 1; }
1429:   const m = $('timing-marker');
1430:   if (m) m.style.left = (g.pos * 100) + '%';
1431: }
1432: 
1433: function timingHit() {
1434:   if (!timingGame || timingGame.done) return;
1435:   const g = timingGame;
1436:   const d = Math.abs(g.pos - g.target);
1437:   let label = 'MISS', cls = 'bad';
1438:   if (d < .045) { g.hits += 1; label = 'PERFECT'; cls = 'perfect'; }
1439:   else if (d < .11) { g.hits += 1; label = 'GOOD'; cls = 'good'; }
1440:   else if (d < .19) { label = 'GRAZED'; cls = 'ok'; }
1441:   g.details.push(label);
1442:   g.round++;
1443:   audio.ui();
1444:   if (label === 'PERFECT') audio.cash();
1445:   const s = $('timing-status');
1446:   if (s) { s.textContent = label; s.className = cls; }
1447:   if (g.round >= g.rounds) {
1448:     g.done = true;
1449:     const cb = g.onComplete;
1450:     const hits = g.hits;
1451:     const details = g.details.slice();
1452:     setTimeout(() => {
1453:       timingGame = null;
1454:       ui.closePanel();
1455:       gameMode = 'play';
1456:       cb?.(hits, details);
1457:     }, 520);
1458:   } else {
1459:     setTimingTarget();
1460:     g.speed = Math.min(1.55, g.speed + .1);
1461:   }
